-- DESIGN MIGRATION, NOT APPLIED. PostgreSQL 16+ syntax baseline.
-- Lock an exact tested image/version before deployment. No extension is required:
-- UUIDs are generated by the application, not by this draft.
-- Do not run against the existing 3188 static site or an existing NBDB database.
-- Application roles, grants, optional RLS, migration runner and backup procedures
-- require a separate reviewed deployment. Composite FKs prevent cross-project
-- references, but they do not replace per-request membership/operation checks.
BEGIN;
CREATE SCHEMA structbio;
SET search_path = structbio, pg_catalog;
CREATE DOMAIN sha256_hex AS text CHECK (VALUE ~ '^[0-9a-f]{64}$');
CREATE DOMAIN object_json AS jsonb CHECK (jsonb_typeof(VALUE) = 'object');

CREATE TABLE projects (
 project_id uuid PRIMARY KEY, name text NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
 state text NOT NULL DEFAULT 'ACTIVE' CHECK (state IN ('ACTIVE','ARCHIVED')),
 policy_version text NOT NULL, ledger_currency text CHECK (ledger_currency ~ '^[A-Z]{3}$'),
 UNIQUE(project_id,ledger_currency), created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE TABLE memberships (
 project_id uuid NOT NULL REFERENCES projects, principal_id uuid NOT NULL,
 role text NOT NULL CHECK (role IN ('viewer','researcher','maintainer','owner')),
 membership_version bigint NOT NULL DEFAULT 1 CHECK (membership_version > 0),
 revoked_at timestamptz, PRIMARY KEY (project_id, principal_id)
);
CREATE TABLE tasks (
 task_id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects,
 created_by uuid NOT NULL, head_revision integer NOT NULL DEFAULT 1 CHECK (head_revision > 0),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE (project_id,task_id), FOREIGN KEY(project_id,created_by) REFERENCES memberships(project_id,principal_id)
);
CREATE TABLE task_revisions (
 project_id uuid NOT NULL, task_id uuid NOT NULL, revision integer NOT NULL CHECK (revision > 0),
 request_payload object_json NOT NULL, request_digest sha256_hex NOT NULL,
 lifecycle text NOT NULL DEFAULT 'ACTIVE' CHECK (lifecycle IN ('ACTIVE','SUPERSEDED','ARCHIVED')),
 created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(project_id,task_id,revision), FOREIGN KEY(project_id,task_id) REFERENCES tasks(project_id,task_id),
 FOREIGN KEY(project_id,created_by) REFERENCES memberships(project_id,principal_id)
);
ALTER TABLE tasks ADD CONSTRAINT task_head_revision_fk
 FOREIGN KEY(project_id,task_id,head_revision) REFERENCES task_revisions(project_id,task_id,revision)
 DEFERRABLE INITIALLY DEFERRED;

CREATE TABLE runs (
 run_id uuid PRIMARY KEY, project_id uuid NOT NULL, task_id uuid NOT NULL, task_revision integer NOT NULL,
 source_run_id uuid, requested_by uuid NOT NULL,
 purpose text NOT NULL CHECK (purpose IN ('ANALYZE','INSPECT')),
 mode text NOT NULL CHECK (mode IN ('agent','reference')),
 model_profile_version text, config_snapshot object_json NOT NULL, config_digest sha256_hex NOT NULL,
 scope_snapshot object_json NOT NULL, scope_digest sha256_hex NOT NULL, policy_version text NOT NULL,
 frozen_spec_id uuid, initial_plan_id uuid, current_plan_id uuid,
 execution_state text NOT NULL DEFAULT 'QUEUED' CHECK (execution_state IN
  ('QUEUED','RUNNING','WAITING_INPUT','WAITING_APPROVAL','RECONCILING','CANCEL_REQUESTED','UNKNOWN','COMPLETED','FAILED','CANCELLED')),
 phase text NOT NULL DEFAULT 'INSPECTING' CHECK (phase IN
  ('INSPECTING','SPECIFYING','PLANNING','EXECUTING','VALIDATING','REPORTING')),
 scientific_status text NOT NULL CHECK (scientific_status IN
  ('NOT_EVALUATED','VALIDATING','ACCEPTED','REJECTED','INCONCLUSIVE','NOT_APPLICABLE')),
 state_version bigint NOT NULL DEFAULT 1 CHECK (state_version > 0),
 next_event_seq bigint NOT NULL DEFAULT 1 CHECK (next_event_seq > 0),
 deadline_at timestamptz NOT NULL, cancel_requested_at timestamptz,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(), started_at timestamptz, ended_at timestamptz,
 UNIQUE(project_id,run_id),
 FOREIGN KEY(project_id,task_id,task_revision) REFERENCES task_revisions(project_id,task_id,revision),
 FOREIGN KEY(project_id,source_run_id) REFERENCES runs(project_id,run_id),
 FOREIGN KEY(project_id,requested_by) REFERENCES memberships(project_id,principal_id),
 CHECK (mode <> 'agent' OR model_profile_version IS NOT NULL),
 CHECK (purpose <> 'INSPECT' OR scientific_status = 'NOT_APPLICABLE'),
 CHECK (deadline_at > created_at),
 CHECK ((execution_state IN ('COMPLETED','FAILED','CANCELLED')) = (ended_at IS NOT NULL)),
 CHECK (ended_at IS NULL OR ended_at >= created_at)
);
CREATE INDEX runs_project_created_idx ON runs(project_id,created_at DESC,run_id);
CREATE INDEX runs_active_idx ON runs(project_id,execution_state) WHERE ended_at IS NULL;
CREATE TABLE run_queue (
 run_id uuid PRIMARY KEY, project_id uuid NOT NULL,
 queue_state text NOT NULL CHECK (queue_state IN ('READY','LEASED','PAUSED','DONE')),
 available_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 lease_owner uuid, lease_expires_at timestamptz, lease_epoch bigint NOT NULL DEFAULT 0 CHECK (lease_epoch >= 0),
 heartbeat_at timestamptz,
 FOREIGN KEY(project_id,run_id) REFERENCES runs(project_id,run_id),
 CHECK ((queue_state='LEASED' AND lease_owner IS NOT NULL AND lease_expires_at IS NOT NULL)
  OR (queue_state<>'LEASED' AND lease_owner IS NULL AND lease_expires_at IS NULL))
);
CREATE INDEX run_queue_ready_idx ON run_queue(available_at,run_id) WHERE queue_state = 'READY';
CREATE INDEX run_queue_expiry_idx ON run_queue(lease_expires_at) WHERE queue_state = 'LEASED';

CREATE TABLE frozen_task_specs (
 frozen_spec_id uuid PRIMARY KEY, project_id uuid NOT NULL, run_id uuid NOT NULL,
 schema_version text NOT NULL, spec_schema_id text NOT NULL CHECK(spec_schema_id ~ '^[A-Za-z][A-Za-z0-9_.-]{0,127}$'),
 spec_artifact_id uuid NOT NULL, payload object_json NOT NULL, payload_digest sha256_hex NOT NULL,
 frozen_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(project_id,run_id), UNIQUE(project_id,run_id,frozen_spec_id),
 FOREIGN KEY(project_id,run_id) REFERENCES runs(project_id,run_id)
);
ALTER TABLE runs ADD CONSTRAINT run_frozen_spec_fk
 FOREIGN KEY(project_id,run_id,frozen_spec_id) REFERENCES frozen_task_specs(project_id,run_id,frozen_spec_id)
 DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE capability_versions (
 capability_id text NOT NULL CHECK (length(capability_id) BETWEEN 1 AND 100), tool_version text NOT NULL,
 manifest object_json NOT NULL, manifest_digest sha256_hex NOT NULL,
 enabled boolean NOT NULL DEFAULT false, checked_at timestamptz,
 PRIMARY KEY(capability_id,tool_version)
);
CREATE TABLE project_capabilities (
 project_id uuid NOT NULL REFERENCES projects, capability_id text NOT NULL, tool_version text NOT NULL,
 enabled boolean NOT NULL DEFAULT false,
 PRIMARY KEY(project_id,capability_id,tool_version),
 FOREIGN KEY(capability_id,tool_version) REFERENCES capability_versions(capability_id,tool_version)
);
CREATE TABLE plans (
 plan_id uuid PRIMARY KEY, project_id uuid NOT NULL, run_id uuid NOT NULL, frozen_spec_id uuid NOT NULL,
 plan_revision integer NOT NULL CHECK (plan_revision > 0), parent_plan_id uuid,
 compile_status text NOT NULL CHECK (compile_status IN ('PASSED','REJECTED')),
 compiler_version text NOT NULL, catalog_digest sha256_hex NOT NULL,
 payload object_json NOT NULL, payload_digest sha256_hex NOT NULL,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(project_id,run_id,plan_id), UNIQUE(project_id,run_id,plan_revision),
 FOREIGN KEY(project_id,run_id,frozen_spec_id) REFERENCES frozen_task_specs(project_id,run_id,frozen_spec_id),
 FOREIGN KEY(project_id,run_id,parent_plan_id) REFERENCES plans(project_id,run_id,plan_id),
 CHECK (parent_plan_id IS NULL OR parent_plan_id <> plan_id)
);
ALTER TABLE runs ADD CONSTRAINT run_initial_plan_fk
 FOREIGN KEY(project_id,run_id,initial_plan_id) REFERENCES plans(project_id,run_id,plan_id)
 DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE runs ADD CONSTRAINT run_current_plan_fk
 FOREIGN KEY(project_id,run_id,current_plan_id) REFERENCES plans(project_id,run_id,plan_id)
 DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE plan_steps (
 project_id uuid NOT NULL, run_id uuid NOT NULL, plan_id uuid NOT NULL,
 step_id text NOT NULL CHECK (length(step_id) BETWEEN 1 AND 100),
 capability_id text NOT NULL, tool_version text NOT NULL,
 request_digest sha256_hex NOT NULL, parameters object_json NOT NULL,
 depends_on jsonb NOT NULL CHECK (jsonb_typeof(depends_on)='array'),
 timeout_ms bigint NOT NULL CHECK (timeout_ms > 0),
 PRIMARY KEY(project_id,run_id,plan_id,step_id),
 FOREIGN KEY(project_id,run_id,plan_id) REFERENCES plans(project_id,run_id,plan_id),
 FOREIGN KEY(project_id,capability_id,tool_version) REFERENCES project_capabilities(project_id,capability_id,tool_version)
);
CREATE TABLE attempts (
 attempt_id uuid PRIMARY KEY, project_id uuid NOT NULL, run_id uuid NOT NULL,
 plan_id uuid, step_id text, attempt_no integer NOT NULL CHECK (attempt_no > 0),
 operation_id uuid NOT NULL UNIQUE, operation_kind text NOT NULL CHECK (operation_kind IN ('MODEL','PREFLIGHT','TOOL','IMPORT')),
 capability_id text, tool_version text,
 request_digest sha256_hex NOT NULL, worker_id uuid, lease_epoch bigint NOT NULL CHECK (lease_epoch >= 0),
 state text NOT NULL CHECK (state IN
  ('CREATED','AUTHORIZED','CLAIMED','RUNNING','SUCCEEDED','FAILED','CANCEL_REQUESTED','CANCELLED','UNKNOWN')),
 provider_request_id text, error_code text, safe_error object_json,
 completion_digest sha256_hex, completion_receipt object_json,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(), started_at timestamptz, ended_at timestamptz,
 UNIQUE(project_id,run_id,attempt_id), UNIQUE(project_id,operation_id), UNIQUE(project_id,run_id,operation_id),
 UNIQUE(project_id,run_id,plan_id,step_id,attempt_no),
 FOREIGN KEY(project_id,run_id) REFERENCES runs(project_id,run_id),
 FOREIGN KEY(project_id,run_id,plan_id,step_id) REFERENCES plan_steps(project_id,run_id,plan_id,step_id),
 FOREIGN KEY(project_id,capability_id,tool_version) REFERENCES project_capabilities(project_id,capability_id,tool_version),
 CHECK ((capability_id IS NULL) = (tool_version IS NULL)),
 CHECK ((plan_id IS NULL) = (step_id IS NULL)),
 CHECK (operation_kind <> 'TOOL' OR plan_id IS NOT NULL),
 CHECK (operation_kind <> 'PREFLIGHT' OR
  (plan_id IS NULL AND step_id IS NULL AND capability_id='inspect_structure' AND capability_id IS NOT NULL AND tool_version IS NOT NULL)),
 CHECK ((state IN ('SUCCEEDED','FAILED','CANCELLED')) = (ended_at IS NOT NULL))
);
CREATE INDEX attempts_run_idx ON attempts(project_id,run_id,created_at,attempt_id);
CREATE INDEX attempts_unknown_idx ON attempts(project_id,state) WHERE state='UNKNOWN';

CREATE TABLE artifacts (
 artifact_id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects,
 origin_kind text NOT NULL CHECK(origin_kind IN ('INPUT','ATTEMPT','CONTROL_EVENT')),
 kind text NOT NULL, media_type text NOT NULL, sha256 sha256_hex NOT NULL,
 byte_count bigint NOT NULL CHECK (byte_count >= 0), storage_key text NOT NULL,
 storage_state text NOT NULL CHECK (storage_state IN ('STAGED','AVAILABLE','MISSING','TOMBSTONED')),
 data_class text NOT NULL, source_metadata object_json NOT NULL,
 producer_run_id uuid, producer_attempt_id uuid, producer_event_id uuid,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(), available_at timestamptz,
 UNIQUE(project_id,artifact_id),
 FOREIGN KEY(project_id,producer_run_id,producer_attempt_id) REFERENCES attempts(project_id,run_id,attempt_id),
 CHECK ((origin_kind='INPUT' AND producer_run_id IS NULL AND producer_attempt_id IS NULL AND producer_event_id IS NULL AND source_metadata <> '{}'::jsonb)
  OR (origin_kind='ATTEMPT' AND producer_run_id IS NOT NULL AND producer_attempt_id IS NOT NULL AND producer_event_id IS NULL)
  OR (origin_kind='CONTROL_EVENT' AND producer_run_id IS NOT NULL AND producer_attempt_id IS NULL AND producer_event_id IS NOT NULL)),
 CHECK (storage_key !~ '(^/|(^|/)\.\.(/|$)|\\)' AND length(storage_key) BETWEEN 1 AND 300),
 CHECK (storage_state <> 'AVAILABLE' OR available_at IS NOT NULL)
);
ALTER TABLE frozen_task_specs ADD CONSTRAINT frozen_spec_artifact_fk
 FOREIGN KEY(project_id,spec_artifact_id) REFERENCES artifacts(project_id,artifact_id)
 DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX artifacts_project_created_idx ON artifacts(project_id,created_at DESC,artifact_id);
CREATE INDEX artifacts_hash_idx ON artifacts(project_id,sha256,byte_count);
CREATE TABLE artifact_parents (
 project_id uuid NOT NULL, child_artifact_id uuid NOT NULL, parent_artifact_id uuid NOT NULL,
 PRIMARY KEY(project_id,child_artifact_id,parent_artifact_id),
 FOREIGN KEY(project_id,child_artifact_id) REFERENCES artifacts(project_id,artifact_id),
 FOREIGN KEY(project_id,parent_artifact_id) REFERENCES artifacts(project_id,artifact_id),
 CHECK (child_artifact_id <> parent_artifact_id)
);
CREATE TABLE task_inputs (
 project_id uuid NOT NULL, task_id uuid NOT NULL, task_revision integer NOT NULL,
 artifact_id uuid NOT NULL, input_role text NOT NULL,
 PRIMARY KEY(project_id,task_id,task_revision,input_role),
 FOREIGN KEY(project_id,task_id,task_revision) REFERENCES task_revisions(project_id,task_id,revision),
 FOREIGN KEY(project_id,artifact_id) REFERENCES artifacts(project_id,artifact_id)
);
CREATE TABLE imports (
 import_id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects, requested_by uuid NOT NULL,
 entry_id text NOT NULL CHECK (length(entry_id) BETWEEN 4 AND 32),
 state text NOT NULL CHECK (state IN ('PENDING','FETCHING','REGISTERED','FAILED')),
 artifact_id uuid, source_url text, retrieved_at timestamptz, error_code text,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(project_id,import_id),
 FOREIGN KEY(project_id,requested_by) REFERENCES memberships(project_id,principal_id),
 FOREIGN KEY(project_id,artifact_id) REFERENCES artifacts(project_id,artifact_id),
 CHECK (state <> 'REGISTERED' OR (artifact_id IS NOT NULL AND source_url IS NOT NULL AND retrieved_at IS NOT NULL))
);
CREATE TABLE validations (
 validation_id uuid PRIMARY KEY, project_id uuid NOT NULL, run_id uuid NOT NULL, frozen_spec_id uuid NOT NULL,
 artifact_id uuid NOT NULL, checker_version text NOT NULL, policy_version text NOT NULL,
 validation_digest sha256_hex NOT NULL,
 scientific_status text NOT NULL CHECK (scientific_status IN ('ACCEPTED','REJECTED','INCONCLUSIVE')),
 evidence object_json NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(project_id,run_id,validation_digest),
 FOREIGN KEY(project_id,run_id,frozen_spec_id) REFERENCES frozen_task_specs(project_id,run_id,frozen_spec_id),
 FOREIGN KEY(project_id,artifact_id) REFERENCES artifacts(project_id,artifact_id)
);
CREATE INDEX validations_artifact_idx ON validations(project_id,artifact_id,created_at DESC);

CREATE TABLE run_events (
 project_id uuid NOT NULL, run_id uuid NOT NULL, seq bigint NOT NULL CHECK (seq > 0),
 event_id uuid NOT NULL UNIQUE, event_type text NOT NULL, schema_version text NOT NULL,
 actor_id uuid, payload object_json NOT NULL CHECK (pg_column_size(payload) <= 65536),
 occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(project_id,run_id,seq), UNIQUE(project_id,event_id), UNIQUE(project_id,run_id,event_id),
 FOREIGN KEY(project_id,run_id) REFERENCES runs(project_id,run_id)
);
ALTER TABLE artifacts ADD CONSTRAINT artifact_control_event_fk
 FOREIGN KEY(project_id,producer_run_id,producer_event_id) REFERENCES run_events(project_id,run_id,event_id)
 DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE event_outbox (
 project_id uuid NOT NULL, event_id uuid PRIMARY KEY,
 available_at timestamptz NOT NULL DEFAULT clock_timestamp(), delivery_attempts integer NOT NULL DEFAULT 0 CHECK (delivery_attempts >= 0),
 delivered_at timestamptz, FOREIGN KEY(project_id,event_id) REFERENCES run_events(project_id,event_id)
);
CREATE INDEX event_outbox_ready_idx ON event_outbox(available_at,event_id) WHERE delivered_at IS NULL;
CREATE TABLE idempotency_keys (
 project_id uuid NOT NULL, principal_id uuid NOT NULL, http_method text NOT NULL,
 resource_scope text NOT NULL, key_digest sha256_hex NOT NULL, request_digest sha256_hex NOT NULL,
 state text NOT NULL CHECK (state IN ('PENDING','COMMITTED','EXPIRED')),
 response_code integer CHECK (response_code BETWEEN 200 AND 599), response_body object_json,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(), response_expires_at timestamptz NOT NULL,
 PRIMARY KEY(project_id,principal_id,http_method,resource_scope,key_digest),
 FOREIGN KEY(project_id,principal_id) REFERENCES memberships(project_id,principal_id),
 CHECK (response_expires_at > created_at),
 CHECK (state <> 'COMMITTED' OR (response_code IS NOT NULL AND response_body IS NOT NULL))
);

-- Fixed integer units. Money units are 1e-6 of the selected project ledger currency.
-- USD is an example, not an implicit currency or a measured-price claim.
-- A configured model/currency/price_version and strict provider maxima are required.
CREATE TABLE budget_accounts (
 account_id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects, run_id uuid,
 scope text NOT NULL CHECK (scope IN ('RUN','PROJECT_PERIOD')),
 period_start timestamptz, period_end timestamptz,
 metric text NOT NULL CHECK (metric IN ('input_tokens','output_tokens','model_calls','cpu_ms','tool_attempts','money_microunits')),
 currency text,
 limit_units bigint NOT NULL CHECK (limit_units >= 0),
 reserved_units bigint NOT NULL DEFAULT 0 CHECK (reserved_units >= 0),
 confirmed_units bigint NOT NULL DEFAULT 0 CHECK (confirmed_units >= 0),
 unknown_reserved_units bigint NOT NULL DEFAULT 0 CHECK (unknown_reserved_units >= 0 AND unknown_reserved_units <= reserved_units),
 account_version bigint NOT NULL DEFAULT 1 CHECK (account_version > 0),
 UNIQUE(project_id,account_id,metric),
 FOREIGN KEY(project_id,run_id) REFERENCES runs(project_id,run_id),
 FOREIGN KEY(project_id,currency) REFERENCES projects(project_id,ledger_currency),
 CHECK ((scope='RUN' AND run_id IS NOT NULL AND period_start IS NULL AND period_end IS NULL)
  OR (scope='PROJECT_PERIOD' AND run_id IS NULL AND period_start IS NOT NULL AND period_end IS NOT NULL AND period_end > period_start)),
 CHECK ((metric='money_microunits' AND currency IS NOT NULL)
  OR (metric<>'money_microunits' AND currency IS NULL))
 -- No CHECK(confirmed+reserved<=limit): authoritative late charges must still be
 -- recorded even when estimates drift. New reservations must fail when over cap.
);
CREATE UNIQUE INDEX budget_run_dimension_uq ON budget_accounts(project_id,run_id,metric) WHERE scope='RUN';
CREATE UNIQUE INDEX budget_project_dimension_uq ON budget_accounts(project_id,period_start,period_end,metric) WHERE scope='PROJECT_PERIOD';
CREATE TABLE budget_reservations (
 reservation_id uuid PRIMARY KEY, project_id uuid NOT NULL, run_id uuid NOT NULL,
 operation_id uuid NOT NULL UNIQUE, pricing_snapshot object_json NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(project_id,reservation_id),
 FOREIGN KEY(project_id,run_id) REFERENCES runs(project_id,run_id),
 FOREIGN KEY(project_id,run_id,operation_id) REFERENCES attempts(project_id,run_id,operation_id)
);
CREATE TABLE usage_entries (
 usage_id uuid PRIMARY KEY, project_id uuid NOT NULL, reservation_id uuid NOT NULL,
 metric text NOT NULL CHECK (metric IN ('input_tokens','output_tokens','model_calls','cpu_ms','tool_attempts','money_microunits')),
 usage_version integer NOT NULL CHECK (usage_version > 0),
 certainty text NOT NULL CHECK (certainty IN ('ESTIMATED','CONFIRMED','UNKNOWN')),
 quantity bigint CHECK (quantity >= 0), currency text, price_version text,
 provider_request_id text, source text NOT NULL,
 observed_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(project_id,reservation_id,metric,usage_version), UNIQUE(project_id,reservation_id,metric,usage_id),
 FOREIGN KEY(project_id,reservation_id) REFERENCES budget_reservations(project_id,reservation_id),
 FOREIGN KEY(project_id,currency) REFERENCES projects(project_id,ledger_currency),
 CHECK ((certainty='UNKNOWN' AND quantity IS NULL) OR (certainty<>'UNKNOWN' AND quantity IS NOT NULL)),
 CHECK ((metric='money_microunits' AND currency IS NOT NULL AND currency ~ '^[A-Z]{3}$' AND price_version IS NOT NULL)
  OR (metric<>'money_microunits' AND currency IS NULL AND price_version IS NULL))
);
CREATE TABLE budget_reservation_lines (
 project_id uuid NOT NULL, reservation_id uuid NOT NULL, account_id uuid NOT NULL,
 metric text NOT NULL,
 state text NOT NULL CHECK (state IN ('RESERVED','UNKNOWN','SETTLED','RELEASED')),
 reserved_units bigint NOT NULL CHECK (reserved_units >= 0),
 applied_quantity bigint NOT NULL DEFAULT 0 CHECK (applied_quantity >= 0),
 applied_usage_id uuid, line_version bigint NOT NULL DEFAULT 1 CHECK (line_version > 0),
 PRIMARY KEY(project_id,reservation_id,account_id),
 FOREIGN KEY(project_id,reservation_id) REFERENCES budget_reservations(project_id,reservation_id),
 FOREIGN KEY(project_id,account_id,metric) REFERENCES budget_accounts(project_id,account_id,metric),
 FOREIGN KEY(project_id,reservation_id,metric,applied_usage_id) REFERENCES usage_entries(project_id,reservation_id,metric,usage_id),
 CHECK (state <> 'SETTLED' OR applied_usage_id IS NOT NULL),
 CHECK (state NOT IN ('SETTLED','RELEASED') OR reserved_units=0)
);
CREATE INDEX budget_unresolved_idx ON budget_reservation_lines(project_id,state) WHERE state IN ('RESERVED','UNKNOWN');

CREATE TABLE storage_quota_accounts (
 account_id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects, run_id uuid,
 scope text NOT NULL CHECK(scope IN ('PROJECT','RUN')),
 limit_bytes bigint NOT NULL CHECK(limit_bytes>=0), reserved_bytes bigint NOT NULL DEFAULT 0 CHECK(reserved_bytes>=0),
 retained_bytes bigint NOT NULL DEFAULT 0 CHECK(retained_bytes>=0), quota_version bigint NOT NULL DEFAULT 1 CHECK(quota_version>0),
 UNIQUE(project_id,account_id), FOREIGN KEY(project_id,run_id) REFERENCES runs(project_id,run_id),
 CHECK((scope='PROJECT' AND run_id IS NULL) OR (scope='RUN' AND run_id IS NOT NULL))
);
CREATE UNIQUE INDEX storage_project_uq ON storage_quota_accounts(project_id) WHERE scope='PROJECT';
CREATE UNIQUE INDEX storage_run_uq ON storage_quota_accounts(project_id,run_id) WHERE scope='RUN';
CREATE TABLE storage_reservations (
 reservation_id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects, run_id uuid,
 operation_id uuid NOT NULL UNIQUE, operation_kind text NOT NULL CHECK(operation_kind IN ('UPLOAD','IMPORT','TOOL')),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(), UNIQUE(project_id,reservation_id),
 FOREIGN KEY(project_id,run_id) REFERENCES runs(project_id,run_id),
 CHECK(operation_kind<>'TOOL' OR run_id IS NOT NULL)
);
CREATE TABLE storage_reservation_lines (
 project_id uuid NOT NULL, reservation_id uuid NOT NULL, account_id uuid NOT NULL,
 state text NOT NULL CHECK(state IN ('RESERVED','UNKNOWN','SETTLED','RELEASED')),
 reserved_bytes bigint NOT NULL CHECK(reserved_bytes>=0), retained_bytes bigint NOT NULL DEFAULT 0 CHECK(retained_bytes>=0),
 line_version bigint NOT NULL DEFAULT 1 CHECK(line_version>0),
 PRIMARY KEY(project_id,reservation_id,account_id),
 FOREIGN KEY(project_id,reservation_id) REFERENCES storage_reservations(project_id,reservation_id),
 FOREIGN KEY(project_id,account_id) REFERENCES storage_quota_accounts(project_id,account_id),
 CHECK(state NOT IN ('SETTLED','RELEASED') OR reserved_bytes=0)
);

CREATE TABLE feedback_issues (
 feedback_id uuid PRIMARY KEY, project_id uuid NOT NULL, run_id uuid NOT NULL,
 submitted_by uuid NOT NULL, artifact_id uuid, report_version text, field_ref text,
 category text NOT NULL, description text NOT NULL CHECK (length(description) BETWEEN 1 AND 4000),
 status text NOT NULL DEFAULT 'NEEDS_REPRODUCTION' CHECK (status IN ('NEEDS_REPRODUCTION','REPRODUCED','DISPUTED','RESOLVED')),
 version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
 resolution_type text CHECK(resolution_type IN ('FIXED','NOT_A_DEFECT','DUPLICATE')),
 regression_case_ref text, fix_version text,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(project_id,feedback_id),
 FOREIGN KEY(project_id,run_id) REFERENCES runs(project_id,run_id),
 FOREIGN KEY(project_id,submitted_by) REFERENCES memberships(project_id,principal_id),
 FOREIGN KEY(project_id,artifact_id) REFERENCES artifacts(project_id,artifact_id),
 CHECK (status <> 'RESOLVED' OR resolution_type IS NOT NULL),
 CHECK (resolution_type IS DISTINCT FROM 'FIXED' OR
  (regression_case_ref IS NOT NULL AND length(regression_case_ref)>0 AND fix_version IS NOT NULL AND length(fix_version)>0))
);
CREATE INDEX feedback_project_status_idx ON feedback_issues(project_id,status,created_at,feedback_id);
CREATE TABLE feedback_history (
 project_id uuid NOT NULL, feedback_id uuid NOT NULL, version bigint NOT NULL CHECK(version>0),
 changed_by uuid NOT NULL, status text NOT NULL CHECK (status IN ('NEEDS_REPRODUCTION','REPRODUCED','DISPUTED','RESOLVED')),
 reason text NOT NULL CHECK(length(reason)>0), evidence_refs jsonb NOT NULL CHECK(jsonb_typeof(evidence_refs)='array'),
 resolution_type text CHECK(resolution_type IN ('FIXED','NOT_A_DEFECT','DUPLICATE')),
 regression_case_ref text, fix_version text, created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(project_id,feedback_id,version),
 FOREIGN KEY(project_id,feedback_id) REFERENCES feedback_issues(project_id,feedback_id),
 FOREIGN KEY(project_id,changed_by) REFERENCES memberships(project_id,principal_id),
 CHECK(status='NEEDS_REPRODUCTION' OR jsonb_array_length(evidence_refs)>0),
 CHECK(status<>'RESOLVED' OR resolution_type IS NOT NULL),
 CHECK(resolution_type IS DISTINCT FROM 'FIXED' OR
  (regression_case_ref IS NOT NULL AND length(regression_case_ref)>0 AND fix_version IS NOT NULL AND length(fix_version)>0))
);

-- Immutability guards: schema drafts protect canonical facts even if an adapter
-- accidentally issues UPDATE. They do not protect against a database superuser.
CREATE FUNCTION deny_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION '% is append-only', TG_TABLE_NAME USING ERRCODE='23514'; END;
$$;
CREATE FUNCTION guard_request_payload() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF ROW(NEW.project_id,NEW.task_id,NEW.revision,NEW.request_payload,NEW.request_digest,NEW.created_by,NEW.created_at)
  IS DISTINCT FROM ROW(OLD.project_id,OLD.task_id,OLD.revision,OLD.request_payload,OLD.request_digest,OLD.created_by,OLD.created_at)
 THEN RAISE EXCEPTION 'task revision payload is immutable' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END;
$$;
CREATE FUNCTION guard_run_snapshot() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF ROW(NEW.project_id,NEW.task_id,NEW.task_revision,NEW.source_run_id,NEW.requested_by,
        NEW.purpose,NEW.mode,NEW.model_profile_version,NEW.config_snapshot,NEW.config_digest,
        NEW.scope_snapshot,NEW.scope_digest,NEW.policy_version,NEW.deadline_at,NEW.created_at)
  IS DISTINCT FROM ROW(OLD.project_id,OLD.task_id,OLD.task_revision,OLD.source_run_id,OLD.requested_by,
        OLD.purpose,OLD.mode,OLD.model_profile_version,OLD.config_snapshot,OLD.config_digest,
        OLD.scope_snapshot,OLD.scope_digest,OLD.policy_version,OLD.deadline_at,OLD.created_at)
 THEN RAISE EXCEPTION 'run request/config/total deadline is immutable' USING ERRCODE='23514'; END IF;
 IF OLD.frozen_spec_id IS NOT NULL AND NEW.frozen_spec_id IS DISTINCT FROM OLD.frozen_spec_id
 THEN RAISE EXCEPTION 'frozen spec cannot be replaced' USING ERRCODE='23514'; END IF;
 IF OLD.initial_plan_id IS NOT NULL AND NEW.initial_plan_id IS DISTINCT FROM OLD.initial_plan_id
 THEN RAISE EXCEPTION 'initial plan cannot be replaced' USING ERRCODE='23514'; END IF;
 IF NEW.current_plan_id IS NOT NULL AND NOT EXISTS
  (SELECT 1 FROM structbio.plans p WHERE p.project_id=NEW.project_id AND p.run_id=NEW.run_id
   AND p.plan_id=NEW.current_plan_id AND p.compile_status='PASSED' AND p.frozen_spec_id=NEW.frozen_spec_id)
 THEN RAISE EXCEPTION 'current plan must pass compilation and bind the same frozen spec' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END;
$$;
CREATE TRIGGER run_snapshot_guard BEFORE UPDATE ON runs FOR EACH ROW EXECUTE FUNCTION guard_run_snapshot();
CREATE FUNCTION guard_artifact_content() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF ROW(NEW.project_id,NEW.origin_kind,NEW.kind,NEW.media_type,NEW.sha256,NEW.byte_count,NEW.storage_key,
        NEW.producer_run_id,NEW.producer_attempt_id,NEW.producer_event_id,NEW.source_metadata,NEW.created_at)
  IS DISTINCT FROM ROW(OLD.project_id,OLD.origin_kind,OLD.kind,OLD.media_type,OLD.sha256,OLD.byte_count,OLD.storage_key,
        OLD.producer_run_id,OLD.producer_attempt_id,OLD.producer_event_id,OLD.source_metadata,OLD.created_at)
 THEN RAISE EXCEPTION 'artifact content identity is immutable; create a new artifact' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END;
$$;
CREATE TRIGGER artifact_content_guard BEFORE UPDATE ON artifacts FOR EACH ROW EXECUTE FUNCTION guard_artifact_content();
CREATE FUNCTION guard_attempt_identity() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF ROW(NEW.project_id,NEW.run_id,NEW.plan_id,NEW.step_id,NEW.attempt_no,NEW.operation_id,
        NEW.operation_kind,NEW.capability_id,NEW.tool_version,NEW.request_digest,NEW.worker_id,NEW.lease_epoch,NEW.created_at)
  IS DISTINCT FROM ROW(OLD.project_id,OLD.run_id,OLD.plan_id,OLD.step_id,OLD.attempt_no,OLD.operation_id,
        OLD.operation_kind,OLD.capability_id,OLD.tool_version,OLD.request_digest,OLD.worker_id,OLD.lease_epoch,OLD.created_at)
 THEN RAISE EXCEPTION 'attempt identity/fencing snapshot is immutable' USING ERRCODE='23514'; END IF;
 IF OLD.completion_digest IS NOT NULL AND
  ROW(NEW.completion_digest,NEW.completion_receipt) IS DISTINCT FROM ROW(OLD.completion_digest,OLD.completion_receipt)
 THEN RAISE EXCEPTION 'completion receipt is immutable' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END;
$$;
CREATE TRIGGER attempt_identity_guard BEFORE UPDATE ON attempts FOR EACH ROW EXECUTE FUNCTION guard_attempt_identity();
CREATE TRIGGER revision_payload_guard BEFORE UPDATE ON task_revisions FOR EACH ROW EXECUTE FUNCTION guard_request_payload();
CREATE TRIGGER revision_delete_guard BEFORE DELETE ON task_revisions FOR EACH ROW EXECUTE FUNCTION deny_change();
CREATE TRIGGER frozen_spec_guard BEFORE UPDATE OR DELETE ON frozen_task_specs FOR EACH ROW EXECUTE FUNCTION deny_change();
CREATE TRIGGER plan_guard BEFORE UPDATE OR DELETE ON plans FOR EACH ROW EXECUTE FUNCTION deny_change();
CREATE TRIGGER step_guard BEFORE UPDATE OR DELETE ON plan_steps FOR EACH ROW EXECUTE FUNCTION deny_change();
CREATE TRIGGER validation_guard BEFORE UPDATE OR DELETE ON validations FOR EACH ROW EXECUTE FUNCTION deny_change();
CREATE TRIGGER event_guard BEFORE UPDATE OR DELETE ON run_events FOR EACH ROW EXECUTE FUNCTION deny_change();
CREATE TRIGGER usage_guard BEFORE UPDATE OR DELETE ON usage_entries FOR EACH ROW EXECUTE FUNCTION deny_change();
CREATE TRIGGER feedback_history_guard BEFORE UPDATE OR DELETE ON feedback_history FOR EACH ROW EXECUTE FUNCTION deny_change();

-- Terminal and delivery flags are computed by business services from the full
-- required-artifact + validation set, not from exit code or this view alone.
CREATE VIEW run_acceptance_candidates AS
 SELECT project_id,run_id,frozen_spec_id,current_plan_id,execution_state,scientific_status
 FROM runs WHERE purpose='ANALYZE' AND execution_state='COMPLETED' AND scientific_status='ACCEPTED';
COMMIT;
